// Utility styling functions for Notification Items based on categories/types
function getCategoryIcon(category) {
  switch (category) {
    case 'booking':
      return <Calendar className="w-5 h-5 text-indigo-400" />;
    case 'payment':
      return <DollarSign className="w-5 h-5 text-emerald-400" />;
    case 'system':
      return <AlertTriangle className="w-5 h-5 text-amber-400" />;
    default:
      return <Bell className="w-5 h-5 text-slate-400" />;
  }
}

function getCategoryIconStyles(category) {
  switch (category) {
    case 'booking':
      return 'bg-indigo-500/10 border-indigo-500/30 text-indigo-300';
    case 'payment':
      return 'bg-emerald-500/10 border-emerald-500/30 text-emerald-300';
    case 'system':
      return 'bg-amber-500/10 border-amber-500/30 text-amber-300';
    default:
      return 'bg-slate-500/10 border-slate-500/30 text-slate-300';
  }
}

function getMicroBadgeIcon(type) {
  switch (type) {
    case 'booking_request':
      return '⌛';
    case 'payment_success':
      return '✓';
    case 'review_received':
      return '★';
    case 'system_alert':
      return '⚠';
    default:
      return '•';
  }
}

function getMicroBadgeStyles(type) {
  switch (type) {
    case 'booking_request':
      return 'bg-indigo-600';
    case 'payment_success':
      return 'bg-emerald-600';
    case 'review_received':
      return 'bg-amber-500';
    case 'system_alert':
      return 'bg-rose-500';
    default:
      return 'bg-slate-600';
  }
}
