                  className="w-full py-4 rounded-xl bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 hover:opacity-95 text-white font-bold transition-all duration-300 shadow-lg shadow-indigo-500/10 flex items-center justify-center gap-2"
                >
                  <Lock className="w-4 h-4" />
                  Proceed to Secure Checkout
                </button>
              </div>
            )}

            {checkoutStep === 'processing' && (
              <div className="p-12 flex flex-col items-center justify-center text-center">
                <Loader2 className="w-12 h-12 text-indigo-400 animate-spin mb-6" />
                <h4 className="text-xl font-bold text-white mb-2">Processing secure payment...</h4>
                <p className="text-sm text-slate-400 max-w-sm">
