                </p>
                {/* Simulated Loading Skeleton Grid */}
                <div className="w-full mt-8 space-y-3">
                  <div className="h-4 bg-slate-800 rounded animate-pulse w-3/4 mx-auto" />
                  <div className="h-4 bg-slate-800 rounded animate-pulse w-5/6 mx-auto" />
                  <div className="h-4 bg-slate-800 rounded animate-pulse w-2/3 mx-auto" />
                </div>
              </div>
            )}

            {checkoutStep === 'success' && (
              <div className="p-12 flex flex-col items-center justify-center text-center">
                <div className="w-16 h-16 rounded-full bg-emerald-500/20 border border-emerald-500/30 flex items-center justify-center mb-6">
                  <Check className="w-8 h-8 text-emerald-400" />
                </div>
                <h4 className="text-2xl font-extrabold text-white mb-2">Your subscription is active!</h4>
                <p className="text-sm text-slate-300 max-w-sm mb-8">
                  Welcome to the {selectedPlan.name} Tier! We have successfully updated your workspace access and premium modules are now fully unlocked.
                </p>
                <button 
                  onClick={closeCheckout}
                  className="w-full py-3.5 rounded-xl bg-white/10 hover:bg-white/15 text-white font-semibold transition-all duration-200 border border-white/10"
                >
                  Enter Workspace
                </button>
              </div>
            )}

          </div>
        </div>
      )}

    </div>
  );
}
