      name: 'Dr. Evelyn Carter',
      role: 'Founder, HealthSync',
      avatar: 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80'
    },
    actionable: true,
    actions: [{ label: 'Schedule Call', type: 'call', primary: true }]
  },
  {
    type: 'payment',
    title: 'Disbursement Initiated',
    description: 'A payout of $4,320.00 USD was successfully sent to your connected bank account.',
    sender: {
      name: 'Stripe Gateway',
      role: 'Automated Payouts',
      avatar: 'https://images.unsplash.com/photo-1621416894569-0f39ed31d247?auto=format&fit=crop&w=150&q=80'
