];

export default function NotificationCenter() {
  const [notifications, setNotifications] = useState(INITIAL_NOTIFICATIONS);
  const [isOpen, setIsOpen] = useState(true); // Default open for rich presentation
  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState('all');
  const [showSettings, setShowSettings] = useState(false);
  const [soundEnabled, setSoundEnabled] = useState(true);
  const [toasts, setToasts] = useState([]);

  // Settings states
  const [settings, setSettings] = useState({
    emailBids: true,
    emailPayments: true,
    emailMessages: false,
    pushBids: true,
    pushPayments: true,
    pushMessages: true,
  });

  // Audio simulation
  const playSound = () => {
    if (!soundEnabled) return;
    try {
      const audioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const oscillator = audioCtx.createOscillator();
      const gainNode = audioCtx.createGain();

      oscillator.type = 'sine';
      oscillator.frequency.setValueAtTime(587.33, audioCtx.currentTime); // D5
      oscillator.frequency.setValueAtTime(880, audioCtx.currentTime + 0.1); // A5

      gainNode.gain.setValueAtTime(0.05, audioCtx.currentTime);
      gainNode.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + 0.4);

      oscillator.connect(gainNode);
      gainNode.connect(audioCtx.destination);
      oscillator.start();
      oscillator.stop(audioCtx.currentTime + 0.4);
    } catch (e) {
      // AudioContext fallback or silent in restricted environments
    }
  };

  // Add a Toast Alert helper
  const addToast = (message, type = 'success') => {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts((prev) => prev.filter((t) => t.id !== id));
    }, 4000);
  };

  // Simulate incoming notification
  const handleSimulateNotification = () => {
    const randomTemplate = NEW_NOTIFS_POOL[Math.floor(Math.random() * NEW_NOTIFS_POOL.length)];
    const newNotif = {
      ...randomTemplate,
      id: `notif-${Date.now()}`,
      time: 'Just now',
      unread: true,
      pinned: false,
    };
    setNotifications((prev) => [newNotif, ...prev]);
    playSound();
    addToast(`New notification: "${newNotif.title}"`, 'info');
  };

  // Handlers
  const handleMarkAllAsRead = () => {
    setNotifications((prev) => prev.map((n) => ({ ...n, unread: false })));
    addToast('All notifications marked as read', 'success');
  };

  const handleToggleRead = (id) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, unread: !n.unread } : n))
    );
  };

  const handleTogglePin = (id) => {
    setNotifications((prev) =>
      prev.map((n) => {
        if (n.id === id) {
          const updatedState = !n.pinned;
          addToast(updatedState ? 'Notification pinned' : 'Notification unpinned', 'success');
          return { ...n, pinned: updatedState };
        }
        return n;
      })
    );
  };

  const handleDelete = (id) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id));
    addToast('Notification removed', 'info');
  };

  const handleClearAll = () => {
    setNotifications([]);
    addToast('All notifications cleared', 'info');
  };

  const handleActionClick = (notifId, actionType, actionLabel) => {
    setNotifications((prev) =>
      prev.map((n) =>
        n.id === notifId ? { ...n, actionPerformed: actionLabel, unread: false } : n
      )
    );
    addToast(`Action: "${actionLabel}" executed successfully!`, 'success');
  };

  const toggleSetting = (key) => {
    setSettings((prev) => ({ ...prev, [key]: !prev[key] }));
    addToast('Notification preferences updated', 'success');
  };

  // Filter and Search Logic
  const filteredNotifications = useMemo(() => {
    return notifications
      .filter((n) => {
        if (activeTab === 'all') return true;
        return n.type === activeTab;
      })
      .filter((n) => {
        if (!searchQuery) return true;
        const query = searchQuery.toLowerCase();
        return (
          n.title.toLowerCase().includes(query) ||
          n.description.toLowerCase().includes(query) ||
          n.sender.name.toLowerCase().includes(query)
        );
      })
      .sort((a, b) => {
        // Pinned notifications stay at the top
        if (a.pinned && !b.pinned) return -1;
        if (!a.pinned && b.pinned) return 1;
        return 0; // maintain time order
      });
  }, [notifications, activeTab, searchQuery]);

  // Unread Count
  const unreadCount = notifications.filter((n) => n.unread).length;

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 flex flex-col justify-start relative overflow-x-hidden font-sans">

      {/* Background Gradients */}
      <div className="absolute top-0 left-0 w-full h-[600px] bg-gradient-to-b from-indigo-900/20 via-purple-900/10 to-transparent pointer-events-none blur-[120px]" />
      <div className="absolute top-[20%] right-[10%] w-[400px] h-[400px] bg-emerald-500/5 rounded-full pointer-events-none blur-[100px]" />

      {/* Real-time Floating Toasts */}
      <div className="fixed bottom-6 right-6 z-50 flex flex-col gap-3 max-w-sm w-full">
        {toasts.map((toast) => (
          <div
            key={toast.id}
            className="flex items-center justify-between gap-3 p-4 rounded-xl border border-white/10 backdrop-blur-xl bg-slate-900/90 shadow-2xl animate-slide-in transition-all duration-300"
          >
            <div className="flex items-center gap-3">
              <div className={`w-2 h-2 rounded-full ${
                toast.type === 'success' ? 'bg-emerald-500' : 'bg-cyan-400'
              }`} />
              <p className="text-xs font-medium text-slate-200">{toast.message}</p>
            </div>
            <button 
              onClick={() => setToasts((prev) => prev.filter((t) => t.id !== toast.id))}
              className="text-slate-400 hover:text-white transition-colors"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        ))}
      </div>

      {/* Main Header / Navigation Simulation */}
      <header className="border-b border-white/10 bg-slate-900/60 backdrop-blur-md sticky top-0 z-40 px-4 py-3 sm:px-8">
        <div className="max-w-7xl mx-auto flex items-center justify-between">

          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-500 to-purple-600 flex items-center justify-center shadow-lg shadow-indigo-500/20">
              <Sparkles className="w-5 h-5 text-white" />
            </div>
            <div>
              <span className="font-bold text-lg tracking-tight bg-gradient-to-r from-white via-slate-200 to-slate-400 bg-clip-text text-transparent">
                LuminaMarket
              </span>
              <span className="hidden sm:inline-block text-[10px] ml-2 px-2 py-0.5 rounded-full bg-indigo-500/15 text-indigo-300 border border-indigo-500/20 font-mono">
                FREELANCER HUB
              </span>
            </div>
          </div>

          {/* Simulated Quick Stats */}
          <div className="hidden md:flex items-center gap-6 text-sm text-slate-400">
            <div>
              <span className="text-slate-500 text-xs block">Active Contracts</span>
              <span className="font-semibold text-slate-200 flex items-center gap-1">4 Projects <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 inline-block animate-pulse"></span></span>
            </div>
            <div className="h-8 w-[1px] bg-white/10" />
            <div>
              <span className="text-slate-500 text-xs block">Escrow Protected</span>
              <span className="font-semibold text-emerald-400 font-mono">$12,450.00</span>
            </div>
          </div>

          {/* Action Hub & Notification Bell Trigger */}
          <div className="flex items-center gap-4">

            {/* Simulation Trigger button */}
            <button
              onClick={handleSimulateNotification}
              className="hidden sm:flex items-center gap-2 bg-gradient-to-r from-indigo-500 to-pink-500 hover:from-indigo-600 hover:to-pink-600 text-white font-medium text-xs px-3.5 py-2 rounded-xl shadow-lg shadow-indigo-500/10 hover:scale-[1.03] transition-all"
            >
              <Plus className="w-3.5 h-3.5" />
              Simulate Alert
            </button>

            {/* Notification Trigger Button */}
            <div className="relative">
              <button
                onClick={() => setIsOpen(!isOpen)}
                className={`relative p-2.5 rounded-xl transition-all duration-300 border ${
                  isOpen 
                    ? 'bg-indigo-500/10 border-indigo-500/30 text-indigo-400' 
                    : 'bg-white/5 border-white/10 hover:bg-white/10 text-slate-300 hover:text-white'
                }`}
                aria-label="Toggle notifications"
              >
                <Bell className={`w-5.5 h-5.5 ${unreadCount > 0 ? 'animate-bounce' : ''}`} />
                {unreadCount > 0 && (
                  <span className="absolute -top-1 -right-1 flex h-5 w-5 items-center justify-center">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-pink-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-5 w-5 bg-gradient-to-r from-pink-500 to-rose-500 text-[10px] font-bold text-white items-center justify-center">
                      {unreadCount}
                    </span>
                  </span>
                )}
              </button>

              {/* Dropdown Container */}
              {isOpen && (
                <div className="absolute right-0 mt-3 w-[calc(100vw-2rem)] sm:w-[480px] origin-top-right rounded-2xl backdrop-blur-xl bg-slate-900/95 border border-white/10 shadow-2xl shadow-black/60 overflow-hidden z-50 transition-all duration-300">

                  {/* Glassmorphic Top Glow Banner */}
                  <div className="h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500" />

                  {/* Header */}
                  <div className="p-4 border-b border-white/10 flex items-center justify-between bg-slate-900/40">
                    <div className="flex items-center gap-2">
                      <h3 className="font-bold text-slate-100 flex items-center gap-2">
                        Notifications
                        <span className="px-2 py-0.5 rounded-full bg-slate-800 text-xs text-slate-400 font-mono">
                          {notifications.length}
