                          <CheckCheck className="w-4 h-4 text-cyan-400" />
                        </button>
                      )}
                    </div>
                  </div>

                  {/* Notification Dropdown Body */}
                  {!showSettings ? (
                    <>
                      {/* Search & Tabs */}
                      <div className="p-3 border-b border-white/5 bg-slate-900/20 space-y-2">
                        {/* Search Bar */}
                        <div className="relative">
                          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-slate-500" />
                          <input
                            type="text"
                            placeholder="Filter by keyword, project, client..."
                            value={searchQuery}
                            onChange={(e) => setSearchQuery(e.target.value)}
                            className="w-full bg-slate-950/80 border border-white/5 focus:border-indigo-500/50 rounded-xl pl-9 pr-8 py-1.5 text-xs text-slate-200 placeholder-slate-500 outline-none transition-all"
                          />
                          {searchQuery && (
                            <button
                              onClick={() => setSearchQuery('')}
                              className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-white"
                            >
                              <X className="w-3 h-3" />
                            </button>
                          )}
                        </div>

                        {/* Category Filter Pills */}
                        <div className="flex gap-1 overflow-x-auto scrollbar-none py-1">
                          {[
                            { id: 'all', label: 'All', icon: SlidersHorizontal },
                            { id: 'project', label: 'Bids', icon: Briefcase, color: 'text-indigo-400' },
                            { id: 'payment', label: 'Payments', icon: DollarSign, color: 'text-emerald-400' },
                            { id: 'message', label: 'Chats', icon: MessageSquare, color: 'text-cyan-400' },
                            { id: 'system', label: 'System', icon: ShieldAlert, color: 'text-amber-400' },
                          ].map((tab) => {
                            const TabIcon = tab.icon;
                            const count = tab.id === 'all' 
                              ? notifications.length 
                              : notifications.filter(n => n.type === tab.id).length;

                            return (
                              <button
                                key={tab.id}
                                onClick={() => setActiveTab(tab.id)}
                                className={`flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium whitespace-nowrap transition-all ${
                                  activeTab === tab.id
                                    ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/30 shadow-sm'
                                    : 'bg-white/5 hover:bg-white/10 text-slate-400 border border-transparent'
                                }`}
                              >
                                <TabIcon className={`w-3 h-3 ${tab.color || 'text-slate-400'}`} />
                                <span>{tab.label}</span>
                                <span className="text-[10px] opacity-60">({count})</span>
                              </button>
                            );
                          })}
                        </div>
                      </div>

                      {/* Scrollable Notifications List */}
                      <div className="max-h-[380px] overflow-y-auto divide-y divide-white/5 custom-scrollbar">
                        {filteredNotifications.length > 0 ? (
                          filteredNotifications.map((notif) => {
                            // Category styling helpers
                            const categoryConfig = {
                              project: {
                                bg: 'bg-indigo-500/10',
                                text: 'text-indigo-400',
                                border: 'border-indigo-500/20',
                                icon: Briefcase
                              },
                              payment: {
                                bg: 'bg-emerald-500/10',
                                text: 'text-emerald-400',
                                border: 'border-emerald-500/20',
                                icon: DollarSign
                              },
                              message: {
                                bg: 'bg-cyan-500/10',
                                text: 'text-cyan-400',
                                border: 'border-cyan-500/20',
                                icon: MessageSquare
                              },
                              system: {
                                bg: 'bg-amber-500/10',
                                text: 'text-amber-400',
                                border: 'border-amber-500/20',
                                icon: ShieldAlert
                              }
                            };

                            const config = categoryConfig[notif.type] || categoryConfig.system;
                            const IconComp = config.icon;

                            return (
                              <div
                                key={notif.id}
                                className={`p-4 transition-all duration-300 hover:bg-white/[0.02] flex gap-3 relative group ${
                                  notif.unread ? 'bg-indigo-950/20' : ''
                                } ${notif.pinned ? 'border-l-2 border-indigo-500' : ''}`}
                              >
                                {/* Left Side: Category Icon & Avatar Stack */}
                                <div className="relative flex-shrink-0">
                                  <img
                                    src={notif.sender?.avatar}
                                    alt={notif.sender?.name}
                                    className="w-10 h-10 rounded-xl object-cover ring-2 ring-white/10"
                                  />
                                  {/* Small floating indicator for notification type */}
                                  <div className={`absolute -bottom-1 -right-1 w-5 h-5 rounded-lg ${config.bg} ${config.border} border flex items-center justify-center text-xs shadow-md`}>
                                    <IconComp className={`w-3 h-3 ${config.text}`} />
                                  </div>
                                </div>

                                {/* Content */}
                                <div className="flex-1 space-y-1">
                                  <div className="flex items-start justify-between gap-2">
                                    <div>
                                      <h4 className="text-xs font-semibold text-slate-100 flex items-center gap-1.5 flex-wrap">
                                        {notif.title}
                                        {notif.pinned && (
                                          <span className="text-[9px] px-1.5 py-0.2 rounded bg-indigo-500/20 text-indigo-300 border border-indigo-500/30 flex items-center gap-0.5 font-mono">
                                            <Pin className="w-2.5 h-2.5" /> PINNED
                                          </span>
                                        )}
                                      </h4>
                                      <p className="text-[10px] text-slate-400 font-medium mt-0.5">
                                        {notif.sender?.name} • <span className="opacity-85">{notif.sender?.role}</span>
                                      </p>
                                    </div>
                                    <span className="text-[10px] text-slate-500 whitespace-nowrap font-mono">
                                      {notif.time}
                                    </span>
                                  </div>

                                  <p className="text-xs text-slate-300 leading-relaxed font-normal">
                                    {notif.description}
                                  </p>

                                  {/* Interactive Actions (Inside Notification Card) */}
                                  {notif.actionable && (
