                        <span>Github</span>
                      </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

      </div>

      {/* Embedded Animation CSS for audio visualizer height jumping */}
      <style>{`
        @keyframes pulseHeight {
          0% { height: 10%; }
          100% { height: 100%; }
        }
        @keyframes spin-slow {
          from { transform: rotate(0deg); }
          to { transform: rotate(360deg); }
        }
        .animate-spin-slow {
          animation: spin-slow 8s linear infinite;
        }
      `}</style>
    </div>
  );
}
