  const [newCategory, setNewCategory] = useState('Tech Support');
  const [newPriority, setNewPriority] = useState('Medium');
  const [newMessageText, setNewMessageText] = useState('');

  // Response simulation state
  const [replyText, setReplyText] = useState('');

  // Refresh Simulation
  const handleRefresh = () => {
    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
    }, 800);
  };

  // Filter & Sort Logic
  const filteredAndSortedTickets = useMemo(() => {
    return tickets
      .filter((ticket) => {
        const matchesSearch = 
          ticket.id.toLowerCase().includes(searchTerm.toLowerCase()) ||
          ticket.subject.toLowerCase().includes(searchTerm.toLowerCase()) ||
          ticket.requester.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
          ticket.requester.email.toLowerCase().includes(searchTerm.toLowerCase());

        const matchesStatus = statusFilter === 'All' || ticket.status === statusFilter;
        const matchesPriority = priorityFilter === 'All' || ticket.priority === priorityFilter;
        const matchesCategory = categoryFilter === 'All' || ticket.category === categoryFilter;

        return matchesSearch && matchesStatus && matchesPriority && matchesCategory;
      })
      .sort((a, b) => {
        let valueA = a[sortBy.field];
        let valueB = b[sortBy.field];

        // Deep mapping for requester name
        if (sortBy.field === 'requester') {
          valueA = a.requester.name;
          valueB = b.requester.name;
        }

        if (valueA < valueB) return sortBy.direction === 'asc' ? -1 : 1;
        if (valueA > valueB) return sortBy.direction === 'asc' ? 1 : -1;
        return 0;
      });
  }, [tickets, searchTerm, statusFilter, priorityFilter, categoryFilter, sortBy]);

  // Pagination Logic
  const paginatedTickets = useMemo(() => {
    const startIndex = (currentPage - 1) * rowsPerPage;
    return filteredAndSortedTickets.slice(startIndex, startIndex + rowsPerPage);
  }, [filteredAndSortedTickets, currentPage, rowsPerPage]);

  const totalPages = Math.ceil(filteredAndSortedTickets.length / rowsPerPage) || 1;

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, statusFilter, priorityFilter, categoryFilter, rowsPerPage]);

  // Metrics calculation
  const metrics = useMemo(() => {
    const total = tickets.length;
    const open = tickets.filter(t => t.status === 'Open').length;
    const pending = tickets.filter(t => t.status === 'Pending').length;
    const resolved = tickets.filter(t => t.status === 'Resolved' || t.status === 'Closed').length;
    const urgent = tickets.filter(t => t.priority === 'Urgent' && t.status !== 'Closed').length;
    return { total, open, pending, resolved, urgent };
  }, [tickets]);

  // Bulk actions handlers
  const handleBulkStatusChange = (status) => {
    setTickets(prev => prev.map(t => selectedTickets.includes(t.id) ? { ...t, status } : t));
    setSelectedTickets([]);
  };

  const handleBulkDelete = () => {
    if(confirm(`Are you sure you want to delete the ${selectedTickets.length} selected ticket(s)?`)) {
      setTickets(prev => prev.filter(t => !selectedTickets.includes(t.id)));
      setSelectedTickets([]);
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedTickets(paginatedTickets.map(t => t.id));
    } else {
      setSelectedTickets([]);
    }
  };

  const handleSelectRow = (id) => {
    setSelectedTickets(prev => 
      prev.includes(id) ? prev.filter(item => item !== id) : [...prev, id]
    );
  };

  // Sort Handler
  const handleSort = (field) => {
    setSortBy(prev => ({
      field,
      direction: prev.field === field && prev.direction === 'desc' ? 'asc' : 'desc'
    }));
  };

  // Create Ticket Submit
  const handleCreateTicket = (e) => {
    e.preventDefault();
    if (!newSubject || !newRequesterName || !newRequesterEmail || !newMessageText) {
      alert("Please fill in all required fields.");
      return;
    }

    const newId = `TK-${1000 + tickets.length + 15}`;
    const newTicket = {
      id: newId,
      subject: newSubject,
      requester: {
        name: newRequesterName,
        email: newRequesterEmail,
        avatar: `https://images.unsplash.com/photo-${1500000000000 + Math.floor(Math.random()*1000000)}?w=150`
      },
      category: newCategory,
      status: "Open",
      priority: newPriority,
      createdAt: new Date().toISOString(),
      assignedTo: "Unassigned",
      messages: [
        { sender: newRequesterName, role: "requester", text: newMessageText, time: new Date().toISOString() }
      ]
    };

    setTickets([newTicket, ...tickets]);
    setShowNewModal(false);
    // Reset Form
    setNewSubject('');
    setNewRequesterName('');
    setNewRequesterEmail('');
    setNewMessageText('');
  };

  // Reply Simulator Handler
  const handleAddReply = (ticketId) => {
    if (!replyText.trim()) return;

    setTickets(prev => prev.map(t => {
      if (t.id === ticketId) {
        return {
          ...t,
          status: t.status === 'Open' ? 'Pending' : t.status, // auto move to pending if open
          messages: [
            ...t.messages,
            { sender: "Support Agent", role: "agent", text: replyText, time: new Date().toISOString() }
          ]
        };
      }
      return t;
    }));
    setReplyText('');
  };

  // Toggle single ticket status from row action
  const toggleTicketStatus = (ticketId, nextStatus) => {
    setTickets(prev => prev.map(t => t.id === ticketId ? { ...t, status: nextStatus } : t));
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-100 font-sans relative overflow-hidden pb-16">

      {/* Dynamic Ambient Background Glows */}
      <div className="absolute top-0 left-1/4 w-[500px] h-[500px] bg-indigo-500/10 rounded-full blur-[120px] pointer-events-none"></div>
      <div className="absolute top-1/3 right-1/4 w-[450px] h-[450px] bg-purple-500/10 rounded-full blur-[100px] pointer-events-none"></div>
      <div className="absolute bottom-10 left-1/3 w-[600px] h-[600px] bg-pink-500/5 rounded-full blur-[150px] pointer-events-none"></div>

