              className="px-5 py-3 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 hover:from-indigo-600 hover:to-pink-600 text-white font-semibold rounded-xl shadow-lg shadow-indigo-500/20 transition-all duration-300 hover:scale-[1.02] flex items-center gap-2"
            >
              <Plus className="h-5 w-5" />
              <span>Create Ticket</span>
            </button>
