            {/* Priority Filter */}
            <div className="relative">
              <label className="block text-xs font-semibold text-slate-400 uppercase tracking-wider mb-1.5 ml-1">Priority</label>
              <select
                value={priorityFilter}
                onChange={(e) => setPriorityFilter(e.target.value)}
                className="w-full px-3 py-2.5 bg-slate-950/60 border border-white/10 rounded-xl text-slate-200 focus:outline-none focus:ring-2 focus:ring-indigo-500/50 focus:border-indigo-500 transition-all appearance-none cursor-pointer"
              >
                <option value="All">All Priorities</option>
                <option value="Urgent">Urgent</option>
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
              </select>
              <div className="absolute bottom-3.5 right-3 pointer-events-none text-slate-400">
                <ChevronDown className="h-4 w-4" />
              </div>
            </div>

          </div>

          {/* Expanded Secondary Filters */}
          <div className="mt-4 pt-4 border-t border-white/5 flex flex-wrap items-center justify-between gap-3">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-xs text-slate-400 font-medium mr-2">Category:</span>
              {['All', 'Infrastructure', 'Billing', 'Security', 'Tech Support', 'Feature Request'].map((cat) => (
                <button
                  key={cat}
                  onClick={() => setCategoryFilter(cat)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all duration-200 ${
                    categoryFilter === cat 
                      ? 'bg-indigo-500/20 text-indigo-300 border border-indigo-500/40' 
                      : 'bg-white/5 text-slate-400 border border-transparent hover:bg-white/10 hover:text-slate-200'
                  }`}
                >
                  {cat}
                </button>
              ))}
            </div>

            {/* Clear filters trigger */}
            {(statusFilter !== 'All' || priorityFilter !== 'All' || categoryFilter !== 'All' || searchTerm !== '') && (
              <button
                onClick={() => {
                  setStatusFilter('All');
                  setPriorityFilter('All');
                  setCategoryFilter('All');
                  setSearchTerm('');
                }}
                className="text-xs text-pink-400 hover:text-pink-300 font-semibold flex items-center gap-1.5 transition-all"
              >
                <X className="h-3.5 w-3.5" />
                Reset Filters
              </button>
            )}
          </div>
        </section>

        {/* Bulk Actions Shelf (Appears when tickets are selected) */}
        {selectedTickets.length > 0 && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 mb-4 p-4 rounded-xl bg-gradient-to-r from-indigo-950/80 to-purple-950/80 border border-indigo-500/30 flex flex-col sm:flex-row items-center justify-between gap-3 shadow-lg shadow-indigo-950/50">
            <div className="flex items-center gap-2 text-indigo-200 text-sm font-medium">
              <Zap className="h-4 w-4 text-amber-400 animate-bounce" />
              <span>Selected <strong>{selectedTickets.length}</strong> ticket{selectedTickets.length > 1 ? 's' : ''} for bulk actions</span>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              <button 
                onClick={() => handleBulkStatusChange('Resolved')}
                className="px-3.5 py-1.5 bg-emerald-500/20 text-emerald-300 hover:bg-emerald-500/30 rounded-lg text-xs font-semibold border border-emerald-500/30 transition-all"
              >
                Mark Resolved
              </button>
              <button 
                onClick={() => handleBulkStatusChange('Pending')}
                className="px-3.5 py-1.5 bg-amber-500/20 text-amber-300 hover:bg-amber-500/30 rounded-lg text-xs font-semibold border border-amber-500/30 transition-all"
              >
                Mark Pending
              </button>
              <button 
                onClick={handleBulkDelete}
                className="px-3.5 py-1.5 bg-rose-500/20 text-rose-300 hover:bg-rose-500/30 rounded-lg text-xs font-semibold border border-rose-500/30 transition-all flex items-center gap-1"
              >
                <Trash2 className="h-3.5 w-3.5" />
                Delete Selected
              </button>
              <button 
                onClick={() => setSelectedTickets([])}
                className="px-3 py-1.5 bg-white/5 text-slate-300 hover:bg-white/10 rounded-lg text-xs font-medium transition-all"
