          ) : filteredAndSortedTickets.length === 0 ? (
            /* Empty State Container */
            <div className="text-center py-16 px-4">
              <div className="mx-auto w-16 h-16 rounded-full bg-slate-800/80 flex items-center justify-center text-slate-400 mb-4 border border-white/5">
