          <div className="hidden md:flex items-center gap-2 bg-slate-900/60 px-3 py-1.5 rounded-lg border border-white/5 text-xs text-slate-300">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            Terminal #04 Active
          </div>

          {/* Trigger Bell Button */}
          <button 
            onClick={() => setIsOpen(!isOpen)}
            className={`relative p-3 rounded-xl transition-all duration-300 ${
              isOpen 
                ? 'bg-gradient-to-br from-indigo-500 to-pink-500 text-white scale-[1.05] shadow-lg shadow-indigo-500/30' 
                : 'bg-white/5 text-slate-300 hover:bg-white/10 border border-white/10 hover:scale-[1.05]'
            }`}
            aria-label="Notification Center"
          >
            <Bell className="w-5 h-5" />
            {unreadCount > 0 && (
              <span className="absolute -top-1.5 -right-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-rose-500 text-[10px] font-bold text-white ring-2 ring-slate-950 animate-bounce">
                {unreadCount}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Dynamic Toast Popup */}
      {toast && (
        <div className="fixed bottom-6 right-6 z-50 animate-bounce flex items-center gap-3 px-4 py-3 rounded-xl border backdrop-blur-xl shadow-2xl bg-slate-900/90 border-white/10">
          <div className={`p-1.5 rounded-md ${
            toast.type === 'success' ? 'bg-emerald-500/20 text-emerald-400' :
            toast.type === 'warning' ? 'bg-amber-500/20 text-amber-400' : 'bg-indigo-500/20 text-indigo-400'
          }`}>
            <Sparkles className="w-4 h-4" />
          </div>
          <p className="text-sm font-medium text-slate-100">{toast.message}</p>
        </div>
      )}

      {/* Layout Split: Side Panel (Simulator) & Main (Notification Center Dropdown) */}
      <div className="w-full max-w-5xl grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

        {/* Left Column: Interactive Real-time POS Event Simulator */}
        <div className="lg:col-span-4 bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-6 shadow-xl transition-all duration-300 hover:scale-[1.01]">
          <div className="flex items-center gap-2 mb-4">
            <Sliders className="w-5 h-5 text-indigo-400" />
            <h2 className="text-md font-semibold text-slate-200">Event Simulator</h2>
          </div>
          <p className="text-xs text-slate-400 mb-5 leading-relaxed">
            Click an event below to inject real-time alert triggers directly into the POS Notification Center.
          </p>

          <div className="flex flex-col gap-3">
            <button 
              onClick={() => triggerSimulation('stock')}
              disabled={isLoading}
              className="flex items-center justify-between p-3 rounded-xl bg-amber-500/10 hover:bg-amber-500/20 border border-amber-500/20 transition-all duration-200 text-left group"
            >
              <div className="flex items-center gap-3">
                <AlertTriangle className="w-5 h-5 text-amber-400 group-hover:scale-110 transition-transform" />
                <div>
                  <div className="text-xs font-bold text-amber-300">Low Stock Alert</div>
                  <div className="text-[10px] text-slate-400">Trigger inventory check</div>
                </div>
              </div>
              <PlusCircle className="w-4 h-4 text-amber-400" />
            </button>

            <button 
              onClick={() => triggerSimulation('sale')}
              disabled={isLoading}
              className="flex items-center justify-between p-3 rounded-xl bg-emerald-500/10 hover:bg-emerald-500/20 border border-emerald-500/20 transition-all duration-200 text-left group"
            >
              <div className="flex items-center gap-3">
                <DollarSign className="w-5 h-5 text-emerald-400 group-hover:scale-110 transition-transform" />
                <div>
                  <div className="text-xs font-bold text-emerald-300">Big Transaction</div>
                  <div className="text-[10px] text-slate-400">Log terminal sale</div>
                </div>
              </div>
              <PlusCircle className="w-4 h-4 text-emerald-400" />
            </button>

            <button 
              onClick={() => triggerSimulation('printer')}
              disabled={isLoading}
              className="flex items-center justify-between p-3 rounded-xl bg-rose-500/10 hover:bg-rose-500/20 border border-rose-500/20 transition-all duration-200 text-left group"
            >
              <div className="flex items-center gap-3">
                <Printer className="w-5 h-5 text-rose-400 group-hover:scale-110 transition-transform" />
                <div>
                  <div className="text-xs font-bold text-rose-300">Printer Fault</div>
                  <div className="text-[10px] text-slate-400">Trigger hardware offline</div>
                </div>
              </div>
              <PlusCircle className="w-4 h-4 text-rose-400" />
            </button>

            <button 
              onClick={() => triggerSimulation('system')}
              disabled={isLoading}
              className="flex items-center justify-between p-3 rounded-xl bg-cyan-500/10 hover:bg-cyan-500/20 border border-cyan-500/20 transition-all duration-200 text-left group"
            >
              <div className="flex items-center gap-3">
                <Database className="w-5 h-5 text-cyan-400 group-hover:scale-110 transition-transform" />
                <div>
                  <div className="text-xs font-bold text-cyan-300">System Database</div>
                  <div className="text-[10px] text-slate-400">Optimizations complete</div>
                </div>
              </div>
              <PlusCircle className="w-4 h-4 text-cyan-400" />
            </button>
          </div>

          <div className="mt-6 pt-5 border-t border-white/5">
            <div className="bg-slate-900/80 p-3 rounded-xl border border-white/5 flex gap-2.5 items-start">
              <Info className="w-4 h-4 text-indigo-400 shrink-0 mt-0.5" />
              <p className="text-[11px] text-slate-400 leading-normal">
                Real-time POS environments rely on push alerts to maintain continuous stock metrics, fast cash drawer checkouts, and thermal printer operations.
              </p>
            </div>
          </div>
        </div>

        {/* Right/Main Column: POS Notification Center (Dropdown styled or visible panel) */}
        <div className="lg:col-span-8 flex flex-col items-stretch">
          {isOpen ? (
            <div className="w-full backdrop-blur-xl bg-slate-900/85 border border-white/10 shadow-2xl rounded-2xl overflow-hidden transition-all duration-300 hover:scale-[1.01] hover:border-white/15">

              {/* Dropdown Header */}
              <div className="p-5 border-b border-white/15 bg-gradient-to-r from-slate-900/90 to-slate-950/90 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-indigo-500/20 rounded-xl text-indigo-400 border border-indigo-500/30">
                    <Bell className="w-5 h-5" />
                  </div>
                  <div>
                    <h3 className="text-lg font-bold text-slate-100 flex items-center gap-2">
                      Live Logs 
                      <span className="text-[11px] bg-indigo-500/20 text-indigo-300 px-2 py-0.5 rounded-full border border-indigo-500/30">
                        {unreadCount} Unread
                      </span>
                    </h3>
                    <p className="text-xs text-slate-400">Terminal notifications and critical alerts</p>
                  </div>
                </div>

                {/* Header Actions */}
                <div className="flex items-center gap-2 self-end sm:self-auto">
                  <button 
                    onClick={handleMarkAllRead}
                    disabled={unreadCount === 0}
                    title="Mark all read"
                    className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold rounded-lg bg-white/5 border border-white/10 text-slate-300 hover:bg-white/10 disabled:opacity-40 disabled:pointer-events-none transition-all duration-200"
                  >
                    <CheckCheck className="w-3.5 h-3.5" />
                    Mark all read
                  </button>
                  <button 
                    onClick={handleClearAll}
                    disabled={notifications.length === 0}
                    title="Clear list"
                    className="p-1.5 rounded-lg bg-rose-500/10 border border-rose-500/20 text-rose-400 hover:bg-rose-500/20 transition-all duration-200"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              {/* Filters Area */}
              <div className="px-5 py-3 border-b border-white/5 bg-slate-950/40 flex gap-1.5 overflow-x-auto scrollbar-thin">
                {['all', 'alert', 'transaction', 'system'].map((filter) => (
                  <button
                    key={filter}
                    onClick={() => setActiveFilter(filter)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-all duration-200 whitespace-nowrap ${
                      activeFilter === filter
                        ? 'bg-gradient-to-r from-indigo-500/30 to-purple-500/30 text-indigo-200 border border-indigo-500/40 shadow-inner'
                        : 'text-slate-400 hover:text-slate-200 hover:bg-white/5 border border-transparent'
                    }`}
                  >
                    {filter === 'all' ? 'All Alerts' : `${filter}s`}
                    <span className="ml-1.5 text-[10px] opacity-65 font-bold">
                      ({filter === 'all' ? notifications.length : notifications.filter(n => n.type === filter).length})
                    </span>
                  </button>
                ))}
              </div>

              {/* Notification Queue Container */}
              <div className="max-h-[480px] overflow-y-auto divide-y divide-white/5 custom-scrollbar">

                {isLoading && (
                  <div className="p-4 bg-white/5 animate-pulse flex gap-3">
                    <div className="w-10 h-10 rounded-xl bg-white/10" />
                    <div className="flex-1 space-y-2">
                      <div className="h-3 bg-white/10 rounded w-1/4" />
                      <div className="h-2 bg-white/5 rounded w-3/4" />
                    </div>
                  </div>
                )}

                {filteredNotifications.length === 0 ? (
                  <div className="p-12 text-center flex flex-col items-center justify-center">
                    <div className="w-14 h-14 rounded-full bg-white/5 flex items-center justify-center border border-white/10 mb-4 animate-pulse">
                      <BellOff className="w-6 h-6 text-slate-500" />
                    </div>
                    <p className="text-sm font-semibold text-slate-300">No active notifications</p>
                    <p className="text-xs text-slate-500 max-w-[240px] mt-1">
                      Everything runs smoothly. Simulated events will populate this queue instantly.
                    </p>
                  </div>
                ) : (
                  filteredNotifications.map((notif) => {
                    const isUnread = !notif.read;
                    let iconBg = 'bg-indigo-500/10 text-indigo-400 border-indigo-500/20';
                    let Icon = Bell;

                    if (notif.type === 'alert') {
                      iconBg = 'bg-amber-500/10 text-amber-400 border-amber-500/20';
                      Icon = AlertTriangle;
                    } else if (notif.type === 'transaction') {
                      iconBg = 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20';
                      Icon = DollarSign;
                    } else if (notif.type === 'system') {
                      iconBg = 'bg-rose-500/10 text-rose-400 border-rose-500/20';
                      Icon = Printer;
                    }

                    return (
                      <div 
                        key={notif.id}
                        onClick={() => handleMarkAsRead(notif.id)}
                        className={`p-5 flex gap-4 transition-all duration-300 relative group cursor-pointer ${
                          isUnread 
                            ? 'bg-indigo-500/[0.03] hover:bg-indigo-500/[0.06]' 
                            : 'bg-transparent hover:bg-white/[0.02]'
                        }`}
                      >
                        {/* Glow marker for unread */}
                        {isUnread && (
                          <div className="absolute left-0 top-0 bottom-0 w-[3px] bg-gradient-to-b from-indigo-500 to-pink-500" />
                        )}

                        {/* Event Icon wrapper */}
                        <div className={`w-10 h-10 rounded-xl flex items-center justify-center border shrink-0 transition-transform duration-300 group-hover:scale-105 ${iconBg}`}>
                          <Icon className="w-5 h-5" />
                        </div>

                        {/* Text and Actions block */}
                        <div className="flex-1 min-w-0">
                          <div className="flex items-start justify-between gap-2">
                            <span className={`text-xs font-bold leading-tight ${isUnread ? 'text-white' : 'text-slate-300'}`}>
                              {notif.title}
                            </span>
                            <span className="text-[10px] text-slate-500 whitespace-nowrap shrink-0">{notif.timestamp}</span>
                          </div>

                          <p className="text-xs text-slate-400 mt-1 leading-relaxed">
                            {notif.description}
                          </p>

                          {/* Meta pill badges */}
                          {notif.meta && (
                            <div className="flex flex-wrap gap-2 mt-2.5">
                              {Object.entries(notif.meta).map(([key, value]) => (
                                <span key={key} className="text-[9px] bg-white/5 border border-white/5 text-slate-300 px-2 py-0.5 rounded-md uppercase tracking-wider">
                                  <strong>{key}:</strong> {value}
                                </span>
                              ))}
                            </div>
                          )}

                          {/* Quick action trigger button */}
                          {notif.actionLabel && (
                            <div className="mt-3 flex items-center gap-2">
                              <button
                                onClick={(e) => handleNotifAction(notif, e)}
                                className="inline-flex items-center gap-1 text-[11px] font-bold text-indigo-400 hover:text-indigo-300 bg-indigo-500/10 hover:bg-indigo-500/20 px-2.5 py-1 rounded-md border border-indigo-500/30 transition-all duration-200"
                              >
                                {notif.actionLabel}
                                <ArrowRight className="w-3 h-3" />
                              </button>
                            </div>
                          )}
                        </div>

                        {/* Trash Action */}
                        <div className="opacity-0 group-hover:opacity-100 transition-opacity duration-200 self-start">
                          <button 
                            onClick={(e) => handleDeleteNotification(notif.id, e)}
                            className="p-1.5 rounded-lg text-slate-500 hover:text-rose-400 hover:bg-rose-500/10 transition-colors"
                            title="Remove notification"
                          >
                            <X className="w-3.5 h-3.5" />
                          </button>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>

              {/* Dropdown Footer */}
              <div className="p-4 bg-slate-950/70 border-t border-white/10 flex justify-between items-center text-xs text-slate-400">
                <span className="flex items-center gap-1.5">
                  <ShieldAlert className="w-3.5 h-3.5 text-indigo-400" />
                  Synced with Cloud-HQ
                </span>
                <span className="text-[10px] text-slate-500">
                  Updated real-time
                </span>
              </div>
            </div>
          ) : (
            // Closed State Fallback Panel view
            <div className="bg-white/5 backdrop-blur-xl border border-white/10 rounded-2xl p-10 text-center flex flex-col items-center justify-center transition-all duration-300 hover:scale-[1.01]">
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-indigo-500/10 to-pink-500/10 border border-white/15 flex items-center justify-center mb-4">
                <Bell className="w-8 h-8 text-indigo-400" />
              </div>
              <h3 className="text-lg font-bold text-slate-200">Notification Center is Closed</h3>
              <p className="text-sm text-slate-400 max-w-sm mt-2">
                Toggle the bell icon in the top header menu bar to open and manage transaction logs, low stock warnings, and printer connection signals.
              </p>
              <button 
                onClick={() => setIsOpen(true)}
                className="mt-6 px-5 py-2.5 bg-gradient-to-r from-indigo-500 to-purple-500 hover:from-indigo-600 hover:to-purple-600 text-white rounded-xl text-xs font-bold shadow-lg shadow-indigo-500/20 transition-all duration-300 hover:scale-105"
              >
                Open Dashboard Dropdown
              </button>
            </div>
          )}
        </div>

      </div>
    </div>
  );
}
