    name: 'Range Rover Sport',
    url: 'https://images.unsplash.com/photo-1608508043351-0d014f24c2e8?auto=format&fit=crop&w=800&q=80',
    category: 'SUV'
  }
];

export default function CreateCarModal({ isOpen, onClose, onSave }) {
  const [step, setStep] = useState(1);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showSuccessToast, setShowSuccessToast] = useState(false);

  // Form State
  const [formData, setFormData] = useState({
    make: '',
    model: '',
    category: 'Electric',
    year: '2024',
    transmission: 'Automatic',
    fuelType: 'Electric',
    seats: '5',
    range: '',
    dailyRate: '',
    description: '',
    imageUrl: PRESET_IMAGES[0].url,
    features: {
      autopilot: false,
      heatedSeats: false,
      panoramicRoof: false,
      premiumAudio: false,
      wirelessCharging: false,
      ventilatedSeats: false
    }
  });

  // Custom Image URL Mode State
  const [customImageUrl, setCustomImageUrl] = useState('');
  const [useCustomImage, setUseCustomImage] = useState(false);

  // Validation
  const [errors, setErrors] = useState({});

  const validateStep = (currentStep) => {
    const stepErrors = {};
    if (currentStep === 1) {
      if (!formData.make.trim()) stepErrors.make = 'Brand/Make is required';
      if (!formData.model.trim()) stepErrors.model = 'Model name is required';
      if (!formData.year) stepErrors.year = 'Year is required';
    } else if (currentStep === 2) {
      if (!formData.dailyRate || Number(formData.dailyRate) <= 0) {
        stepErrors.dailyRate = 'Please enter a valid daily rate';
      }
      if (!formData.range || Number(formData.range) <= 0) {
        stepErrors.range = 'Please provide dynamic range or mileage';
      }
    }
    setErrors(stepErrors);
    return Object.keys(stepErrors).length === 0;
  };

  const handleNext = () => {
    if (validateStep(step)) {
      setStep((prev) => Math.min(prev + 1, 3));
    }
  };

  const handleBack = () => {
    setStep((prev) => Math.max(prev - 1, 1));
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: null }));
    }
  };

  const handleFeatureToggle = (featureKey) => {
    setFormData((prev) => ({
      ...prev,
      features: {
        ...prev.features,
        [featureKey]: !prev.features[featureKey]
      }
    }));
  };

  const handlePresetSelect = (url) => {
    setUseCustomImage(false);
    setFormData((prev) => ({ ...prev, imageUrl: url }));
  };

  const handleCustomImageSubmit = (e) => {
    e.preventDefault();
    if (customImageUrl.trim().startsWith('http')) {
      setFormData((prev) => ({ ...prev, imageUrl: customImageUrl }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateStep(3)) return;

    setIsSubmitting(true);

    // Simulate API storage / loading skeleton delay
    await new Promise((resolve) => setTimeout(resolve, 2000));

    setIsSubmitting(false);
    setShowSuccessToast(true);

    if (onSave) {
      onSave(formData);
    }

    setTimeout(() => {
      setShowSuccessToast(false);
      onClose();
      // Reset form
      setStep(1);
      setFormData({
        make: '',
        model: '',
        category: 'Electric',
        year: '2024',
        transmission: 'Automatic',
        fuelType: 'Electric',
        seats: '5',
        range: '',
        dailyRate: '',
        description: '',
        imageUrl: PRESET_IMAGES[0].url,
        features: {
          autopilot: false,
          heatedSeats: false,
          panoramicRoof: false,
          premiumAudio: false,
          wirelessCharging: false,
          ventilatedSeats: false
        }
      });
    }, 1800);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 sm:p-6 md:p-10 bg-slate-950/80 backdrop-blur-md overflow-y-auto">

