                <h3 className="text-lg font-bold text-slate-100 truncate">
                  {formData.make || 'New'} {formData.model || 'Vehicle'}
                </h3>
                <p className="text-xs text-slate-400 line-clamp-1 italic mt-1">
                  "{formData.description || 'Elevate your driving experience to unparalleled levels.'}"
                </p>
              </div>

              {/* Specifications Grid */}
              <div className="grid grid-cols-2 gap-2 pt-3 border-t border-white/5 text-[11px] text-slate-300">
                <div className="flex items-center gap-2">
                  <Gauge className="w-3.5 h-3.5 text-indigo-400" />
                  <span>Range: <strong className="text-slate-100">{formData.range || '0'} mi</strong></span>
                </div>
