                  <Users className="w-3.5 h-3.5 text-indigo-400" />
                  <span>Seats: <strong className="text-slate-100">{formData.seats} Persons</strong></span>
                </div>
              </div>

              {/* Active Features Badges */}
              <div className="flex flex-wrap gap-1 mt-4">
                {Object.entries(formData.features).map(([key, active]) => {
                  if (!active) return null;
                  return (
                    <span 
                      key={key} 
                      className="text-[9px] bg-indigo-500/20 text-indigo-300 border border-indigo-500/30 px-2 py-0.5 rounded-full capitalize"
                    >
                      {key.replace(/([A-Z])/g, ' $1')}
                    </span>
                  );
                })}
              </div>
            </div>
          </div>

          {/* Verification Badge */}
          <div className="mt-6 p-4 rounded-xl bg-slate-950/40 border border-slate-800/80 flex items-center gap-3">
            <div className="p-2 rounded-lg bg-emerald-500/10 text-emerald-400">
              <ShieldCheck className="w-5 h-5" />
            </div>
            <div>
              <p className="text-xs font-semibold text-slate-200">Verified Fleet Protection</p>
              <p className="text-[10px] text-slate-400">All submissions are dynamically audited for secure hosting compliance.</p>
            </div>
          </div>

        </div>

      </div>
    </div>
  );
}
