            </div>
            <div>
              <p className="text-xs font-semibold text-white">{toastMessage.type === 'success' ? 'Settings Update' : 'System Notice'}</p>
              <p className="text-xs text-slate-300 mt-0.5">{toastMessage.text}</p>
            </div>
            <button 
              onClick={() => setShowToast(false)}
              className="text-slate-500 hover:text-white ml-2"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
